import './styles.css'
import { useEffect, useState } from 'react';
import axios from 'axios';
import getMLABDATA from '../Hooks/getMLABDATA';
import { Dropdown, Button } from 'react-bootstrap';

function MLABPage(){
    const[countryList, setCountryList] = useState(['Please Select a Country']);
    const[country, setCountry] = useState(['c','c'])
    const[year, setYear] = useState('2024');
    const[group, setGroup] = useState();
    const[metric, setetric] = useState();
    const[countryListLoaded, setCountryListLoad] = useState(false);
    
    useEffect(()=>{
        //LOAD A LIST OF COUNTRIES THAT HAVE DATA
        const getCountryList = async()=>{
        const cList = await getMLABDATA('all', '2024', 'country', 'compute')
        setCountryList(cList.data);
        setCountryListLoad(true);
        console.log(countryList.data);
        console.log(country);
        } 
        
        

        getCountryList();
    }, [])

    const handleCountrySelect = (sCountry, index) => {
        const data = [...country]
        data[index]={name: sCountry}
        setCountry(data);
        console.log(country);
    }
    
    

    return(
        <div class='MLABPage'>
            <div class="row">
            <div class="col">
            <h2>Selected country: {country[0]}</h2>
            {countryListLoaded &&(
                <>
                <Dropdown>
                <Dropdown.Toggle>
                Select a country
                </Dropdown.Toggle>
                <Dropdown.Menu>
                {countryList.map((countryList)=>(
                    
                    <Dropdown.Item as="button" key={countryList.country} onClick={()=>handleCountrySelect(countryList.country,0)}>{countryList.country}</Dropdown.Item>
                    
                ))}
                </Dropdown.Menu>
                </Dropdown>
                </>
            )}
            </div>
            <div class= "col">
                <h2>Selected country: {country[1]}</h2>
            {countryListLoaded &&(
                <>
                <Dropdown>
                <Dropdown.Toggle>
                Select a country
                </Dropdown.Toggle>
                <Dropdown.Menu>
                {countryList.map((countryList)=>(
                    
                    <Dropdown.Item as="button" key={countryList.country} onClick={()=>handleCountrySelect(countryList.country,1)}>{countryList.country}</Dropdown.Item>
                    
                ))}
                </Dropdown.Menu>
                </Dropdown>
                </>
            )}
                
            </div>
            </div>
        </div>
    )

}

export default MLABPage;
